/** Internal child of the original material research host; explicit memory-only authority for selected excerpts. */
public final class KnowledgeRetrievalScreen extends LinearLayout {
 private interface Action{void run()throws Exception;}
 private final JSONObject held;private JSONObject result=new JSONObject(),context=new JSONObject(),attempt=new JSONObject();private JSONArray selectedIds=new JSONArray();
 private final KnowledgeAiHostScreen.Sources sources;private final KnowledgeAiHostScreen.Preferences preferences;private final Runnable exit;
 private BooleanSupplier entryCheck=()->false;private boolean active,closed,loading,dark;private int pageIndex,readGeneration;
 private final TextView message,reader,previewText;private final EditText question,query,topK;private final Spinner mode;private final LinearLayout hits;private final View[] pages=new View[3];private final ScrollView readerScroll;private final View blockedCheckButton;
 private RequestAuthorizationView authority;private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"retrieval-request");t.setDaemon(true);return t;});private boolean busy;
 private AiKnowledgeRequest.Prepared prepared;private AiKnowledgeRequest.Cancellation cancellation;
 public KnowledgeRetrievalScreen(Context c,JSONObject selected,String initialQuestion,KnowledgeAiHostScreen.Sources s,KnowledgeAiHostScreen.Preferences p,Runnable e)throws Exception{
  super(c);held=new JSONObject(selected.toString());sources=s;preferences=p;exit=e;setOrientation(VERTICAL);setTag("knowledgeRetrievalPage");setSaveEnabled(false);setSaveFromParentEnabled(false);setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);
  text(this,"本机证据检索 · 默认无授权与凭据；可主动授权所选片段请求",null);message=text(this,"先填写检索词并检索；不会默认勾选证据。","retrievalMessage");message.setMaxLines(2);message.setEllipsize(TextUtils.TruncateAt.END);
  LinearLayout nav=new LinearLayout(c);addView(nav);button(nav,"资料选择","retrievalExit",()->{cancel();exit.run();},true);button(nav,"检索列表","retrievalBack",()->back(),true);button(nav,"取消清除","retrievalCancel",()->cancel(),true);button(nav,"未授权检查","retrievalBlockedCheck",()->blockedCheck(),true);blockedCheckButton=nav.findViewWithTag("retrievalBlockedCheck");blockedCheckButton.setVisibility(GONE);
  ScrollView main=new ScrollView(c);pages[0]=main;addView(main,new LayoutParams(-1,0,1));LinearLayout body=new LinearLayout(c);body.setOrientation(VERTICAL);body.setPadding(dp(8),0,dp(8),dp(12));main.addView(body);
  question=edit(body,"研究问题，最多1000个UTF-16单位","retrievalQuestion",initialQuestion);question.setMinLines(1);question.setMaxLines(2);query=edit(body,"明确检索词，最多500个UTF-16单位","retrievalQuery",initialQuestion.length()<=500?initialQuestion:"");query.setSingleLine(true);
  LinearLayout options=new LinearLayout(c);body.addView(options);topK=new EditText(c);topK.setTag("retrievalTopK");topK.setSaveEnabled(false);topK.setSingleLine(true);topK.setText("10");topK.setHint("返回数1..50");topK.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);topK.setTextSize(13);options.addView(topK,new LayoutParams(0,dp(48),1));mode=new Spinner(c);mode.setTag("retrievalMode");mode.setSaveEnabled(false);mode.setAdapter(new ArrayAdapter<>(c,android.R.layout.simple_spinner_dropdown_item,new String[]{"作者观点","时间变化","规则检查","反证 / 冲突","候选比较"}));options.addView(mode,new LayoutParams(0,dp(48),1));
  StringBuilder names=new StringBuilder("本次明确范围：\n");JSONArray materials=held.getJSONArray("materials");for(int i=0;i<materials.length();i++){JSONObject d=materials.getJSONObject(i);names.append(KnowledgeAiHost.identity(d)).append(" · ").append(d.getJSONObject("row").optString("title")).append('\n');}names.append("优先实测本机FTS5 / trigram / BM25，仅为所选资料评分；不支持或无命中明确字面回退。最多10块/每来源3块；不检索originalText。");text(body,names.toString(),"retrievalScope");
  LinearLayout tools=new LinearLayout(c);body.addView(tools);button(tools,"核对并检索","retrievalSearch",()->retrieve(),true);button(tools,"组装证据预览","retrievalPreview",()->preview(),true);hits=new LinearLayout(c);hits.setOrientation(VERTICAL);hits.setTag("retrievalHits");body.addView(hits);
  readerScroll=new ScrollView(c);readerScroll.setTag("retrievalSourceScroll");pages[1]=readerScroll;readerScroll.setVisibility(GONE);addView(readerScroll,new LayoutParams(-1,0,1));LinearLayout reading=new LinearLayout(c);reading.setOrientation(VERTICAL);reading.setPadding(dp(8),0,dp(8),dp(12));readerScroll.addView(reading);reader=text(reading,"","retrievalSourceReader");
  LinearLayout previewPage=new LinearLayout(c);previewPage.setOrientation(VERTICAL);pages[2]=previewPage;previewPage.setVisibility(GONE);addView(previewPage,new LayoutParams(-1,0,1));ScrollView previewScroll=new ScrollView(c);previewPage.addView(previewScroll,new LayoutParams(-1,0,1));LinearLayout previewBody=new LinearLayout(c);previewBody.setOrientation(VERTICAL);previewBody.setPadding(dp(8),0,dp(8),dp(12));previewScroll.addView(previewBody);previewText=text(previewBody,"","retrievalContextReader");authority=new RequestAuthorizationView(c,()->allowed(null));previewBody.addView(authority);authority.expired=()->cancel();button(previewBody,"发送当前已授权证据请求","retrievalSend",()->sendAuthorized(),false);
  message.setOnClickListener(v->{if(allowed(v)){String details=result.has("index")?"\n\n完整索引能力与来源版本\n"+result.optJSONObject("index"):"\n\n本次没有有效索引。";reader.setText(message.getText()+details);show(1);}});
  watch(query,()->invalidate(true));watch(topK,()->invalidate(true));watch(question,()->invalidate(false));mode.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> parent,View v,int position,long id){if(!loading&&allowed(mode))invalidate(false);}public void onNothingSelected(android.widget.AdapterView<?> p){}});
 }
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(LinearLayout parent,String value,String tag){TextView v=new TextView(getContext());v.setText(value);v.setTag(tag);v.setTextSize(14);v.setSaveEnabled(false);v.setTextIsSelectable(true);parent.addView(v,new LayoutParams(-1,-2));return v;}
 private EditText edit(LinearLayout parent,String hint,String tag,String value){EditText v=new EditText(getContext());v.setHint(hint);v.setText(value);v.setTag(tag);v.setSaveEnabled(false);v.setTextSize(14);parent.addView(v,new LayoutParams(-1,-2));return v;}
 private void button(LinearLayout parent,String label,String tag,Action action,boolean weighted){Button b=new Button(getContext());b.setText(label);b.setTextSize(13);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(4),0,dp(4),0);b.setTag(tag);parent.addView(b,weighted?new LayoutParams(0,dp(48),1):new LayoutParams(-1,dp(48)));b.setOnClickListener(v->{if(allowed(v))guard(action);});}
 private void watch(EditText edit,Action action){edit.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(!loading&&allowed(edit))guard(action);}public void afterTextChanged(Editable e){}});}
 public void setEntryCheck(BooleanSupplier check){entryCheck=Objects.requireNonNull(check);}
 public String researchQuestion(){return question.getText().toString();}
 private boolean allowed(View origin){return active&&!closed&&isAttachedToWindow()&&isShown()&&isEnabled()&&entryCheck.getAsBoolean()&&(origin==null||origin.isShown()&&origin.isEnabled());}
 private void guard(Action action){try{action.run();}catch(Exception e){message.setText(e.getMessage()==null?"本机检索操作失败":e.getMessage());}}
 private void checkSources()throws Exception{try{if(sources==null)throw new Exception("完整资料接口未接入");KnowledgeAiHost.confirm(held,sources.current());}catch(Exception e){invalidate(true);show(0);throw e;}}
 private void show(int index){pageIndex=index;blockedCheckButton.setVisibility(index==2?VISIBLE:GONE);for(int i=0;i<3;i++)pages[i].setVisibility(i==index?VISIBLE:GONE);}
 private void invalidate(boolean clearResults){if(authority!=null)authority.clear();busy=false;readGeneration++;if(cancellation!=null)cancellation.cancel();cancellation=null;prepared=null;context=new JSONObject();attempt=new JSONObject();previewText.setText("");if(clearResults){result=new JSONObject();selectedIds=new JSONArray();hits.removeAllViews();reader.setText("");}}
 private void retrieve()throws Exception{
  invalidate(true);checkSources();int limit;try{limit=Integer.parseInt(topK.getText().toString());}catch(Exception e){throw new Exception("返回块数必须为1到50，未截断");}result=KnowledgeSearchIndex.search(held.getJSONArray("materials"),query.getText().toString(),limit);JSONArray items=result.getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject h=items.getJSONObject(i);String stamp=h.optString("publishedAt");if(stamp.isEmpty())stamp="未知";button(hits,"阅读来源 · "+h.getString("sourceKey")+" · "+stamp+" · UTF-16["+h.getInt("charStart")+","+h.getInt("charEnd")+")","retrievalRead"+i,()->readSource(h),false);CheckBox b=new CheckBox(getContext());b.setTag(h.getString("evidenceId"));b.setSaveEnabled(false);b.setText(h.optString("title")+"\n"+h.getString("content"));b.setTextSize(14);hits.addView(b,new LayoutParams(-1,-2));b.setOnCheckedChangeListener((v,checked)->{if(!loading&&allowed(v))guard(()->select(h,b,checked));});}
  message.setText(result.getString("engineLabel")+" · 共"+result.getInt("totalChunks")+"块，命中"+result.getInt("matchedChunks")+"块，返回"+items.length()+"块，topK外遗漏"+result.getInt("omittedByTopK")+"块。未默认选择。实际词："+result.getJSONArray("usedTokens")+"；未用于回退的词："+result.getJSONArray("unusedFallbackTokens")+"；24词上限外遗漏："+result.getJSONArray("tokensBeyondLimit"));paint(this,dark);
 }
 private void select(JSONObject hit,CheckBox box,boolean checked)throws Exception{
  checkSources();JSONArray candidate=new JSONArray();String id=hit.getString("evidenceId");boolean had=false;for(int i=0;i<selectedIds.length();i++){String old=selectedIds.getString(i);if(old.equals(id)){had=true;if(checked)candidate.put(old);}else candidate.put(old);}if(checked&&!had)candidate.put(id);Map<String,String> keys=new HashMap<>();JSONArray items=result.getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject h=items.getJSONObject(i);keys.put(h.getString("evidenceId"),h.getString("sourceKey"));}Map<String,Integer> counts=new HashMap<>();boolean valid=candidate.length()<=10;for(int i=0;i<candidate.length();i++){String key=keys.get(candidate.getString(i));int n=counts.getOrDefault(key,0)+1;counts.put(key,n);if(n>3)valid=false;}if(!valid){loading=true;box.setChecked(had);loading=false;throw new Exception("最多10块、每来源3块；原选择保留，未自动裁剪");}selectedIds=candidate;invalidate(false);message.setText("已明确选择"+selectedIds.length()+"块。组装前会再次核对完整来源版本。");
 }
 private void readSource(JSONObject hit)throws Exception{
  checkSources();JSONObject d=null;JSONArray materials=held.getJSONArray("materials");for(int i=0;i<materials.length();i++)if(KnowledgeAiHost.identity(materials.getJSONObject(i)).equals(hit.getString("sourceKey")))d=materials.getJSONObject(i);if(d==null)throw new Exception("命中来源身份不在明确选择内");JSONObject row=d.getJSONObject("row");String prefix=hit.getString("sourceKey")+"\n原发布时间："+hit.optString("publishedAt")+"\n来源版本："+hit.getJSONObject("reference").getString("rowSha256")+"\n命中位置：row.text UTF-16["+hit.getInt("charStart")+","+hit.getInt("charEnd")+")；保留原换行，非规范化字符串。\n\n完整本机正文\n";SpannableString value=new SpannableString(prefix+row.getString("text")+"\n\n完整 originalText（未检索）\n"+row.optString("originalText")+"\n\n完整来源记录\n"+d.toString(2));int start=prefix.length()+hit.getInt("charStart"),end=prefix.length()+hit.getInt("charEnd");value.setSpan(new BackgroundColorSpan(dark?Color.rgb(80,68,10):Color.rgb(255,236,132)),start,end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);reader.setText(value);show(1);int generation=++readGeneration;reader.post(()->{if(allowed(reader)&&pageIndex==1&&generation==readGeneration&&reader.getLayout()!=null){int line=reader.getLayout().getLineForOffset(start);readerScroll.scrollTo(0,reader.getLayout().getLineTop(line));}});
 }
 private void preview()throws Exception{
  invalidate(false);checkSources();context=KnowledgeRetrieval.context(result,selectedIds,question.getText().toString(),KnowledgeRetrieval.modes()[mode.getSelectedItemPosition()]);String value="所选证据的完整外发提示（仅提示中的片段和元数据将外发）\n\n"+context.getString("prompt");try{if(preferences==null)throw new Exception("非敏感配置接口未接入");prepared=AiKnowledgeRequest.prepareEvidence(preferences.current(),context);authority.bind(Collections.singletonList(prepared));value+="\n\n精确供应商请求body（完整，无截断）\n"+prepared.preview().getJSONObject("requestBody").toString(2);}catch(Exception e){value+="\n\n供应商请求未形成："+e.getMessage()+"；本机上下文仍完整可读。";}value+="\n\n完整本机核对包（来源全文保留本机，以下JSON不是实际外发body）\n"+context.toString(2);previewText.setText(value);show(2);message.setText("已组装明确选入的证据，遗漏边界在预览中；默认无授权与凭据；主动授权仅绑定实际待发送的片段请求。");
 }
 private void blockedCheck()throws Exception{checkSources();if(prepared==null)throw new Exception("尚未形成可核对的供应商请求，请检查非敏感模型配置");cancellation=new AiKnowledgeRequest.Cancellation();attempt=AiKnowledgeRequest.execute(prepared,null,null,cancellation);message.setText("未授权检查："+attempt.optString("status")+" · "+attempt.optString("errorCode")+" · networkAttempted="+attempt.optBoolean("networkAttempted"));}
 public JSONObject currentResult()throws Exception{return new JSONObject(result.toString());}public JSONObject currentContext()throws Exception{return new JSONObject(context.toString());}public JSONObject lastAttempt()throws Exception{return new JSONObject(attempt.toString());}public JSONArray selectedEvidence()throws Exception{return new JSONArray(selectedIds.toString());}
 public void cancel(){if(closed)return;invalidate(true);show(0);message.setText("已取消，检索结果、证据选择和外发预览失效；原宿主完整资料仍保留。");}
 public void setActive(boolean value){active=value;if(!value)cancel();}
 public boolean back(){if(!allowed(null)||pageIndex==0)return false;invalidate(false);show(0);return true;}
 public void close(){if(closed)return;cancel();worker.shutdownNow();closed=true;active=false;setEnabled(false);}
 @Override public void onVisibilityAggregated(boolean visible){super.onVisibilityAggregated(visible);if(!visible&&message!=null)setActive(false);}
 @Override protected void onDetachedFromWindow(){setActive(false);super.onDetachedFromWindow();}
 public void setDarkTheme(boolean value){dark=value;setBackgroundColor(value?Color.rgb(17,26,40):Color.rgb(245,248,252));paint(this,value);}
 private void paint(View v,boolean value){if(v instanceof TextView)((TextView)v).setTextColor(value?Color.rgb(235,241,249):Color.rgb(25,41,62));if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)paint(g.getChildAt(i),value);}}
 private void sendAuthorized()throws Exception{checkSources();if(prepared==null||!authority.ready()||busy)throw new Exception("先预览、核对并主动授权本次证据请求");final AiKnowledgeRequest.Prepared exact=prepared;final AiKnowledgeRequest.Grant grant=authority.authorize(exact);final AiKnowledgeRequest.Cancellation stop=cancellation=new AiKnowledgeRequest.Cancellation();final int ticket=readGeneration;busy=true;worker.execute(()->{try{final JSONObject done=AiKnowledgeRequest.execute(exact,grant,()->authority.acquire(),stop);post(()->{if(ticket!=readGeneration||!allowed(null))return;busy=false;authority.clear();attempt=done;reader.setText(done.toString());show(1);message.setText("证据请求："+done.optString("status")+"；结果需核验，未保存或启动其他请求。");});}catch(Exception e){post(()->{if(ticket==readGeneration&&allowed(null)){busy=false;authority.clear();message.setText("请求组件失败，授权已撤销。");}});}});}
}
